package hashmap;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;

/**
 * Tests generated by Claude from the prompt in PROMPT.md.
 * Uses only the public API plus the package-private capacity() and checkInvariants().
 */
class MyHashMapAiTest {

    /** Key with a controllable hashCode, used to force collisions and negative hashes. */
    private static final class TestKey {
        private final String id;
        private final int hash;

        TestKey(String id, int hash) {
            this.id = id;
            this.hash = hash;
        }

        @Override
        public int hashCode() {
            return hash;
        }

        @Override
        public boolean equals(Object other) {
            return other instanceof TestKey && ((TestKey) other).id.equals(id);
        }
    }

    // ---------------------------------------------------------------- empty map

    @Test
    void newMapIsEmpty() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        assertTrue(map.isEmpty());
        assertEquals(0, map.size());
        map.checkInvariants();
    }

    @Test
    void getOnEmptyMapReturnsNull() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        assertNull(map.get("x"));
    }

    @Test
    void containsKeyOnEmptyMapReturnsFalse() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        assertFalse(map.containsKey("x"));
    }

    @Test
    void removeOnEmptyMapReturnsNullAndKeepsSizeZero() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        assertNull(map.remove("x"));
        assertEquals(0, map.size());
    }

    // ---------------------------------------------------------------- single element

    @Test
    void putSingleElementReturnsNullForNewKey() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        assertNull(map.put("a", 1));
    }

    @Test
    void putSingleElementIsRetrievable() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        map.put("a", 1);
        assertEquals(1, map.get("a"));
        assertTrue(map.containsKey("a"));
        assertEquals(1, map.size());
        assertFalse(map.isEmpty());
        map.checkInvariants();
    }

    @Test
    void removeSingleElementReturnsItsValueAndEmptiesMap() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        map.put("a", 1);
        assertEquals(1, map.remove("a"));
        assertNull(map.get("a"));
        assertTrue(map.isEmpty());
        map.checkInvariants();
    }

    // ---------------------------------------------------------------- duplicates

    @Test
    void putDuplicateKeyReturnsPreviousValue() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        map.put("a", 1);
        assertEquals(1, map.put("a", 2));
    }

    @Test
    void putDuplicateKeyOverwritesValue() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        map.put("a", 1);
        map.put("a", 2);
        assertEquals(2, map.get("a"));
    }

    @Test
    void putDuplicateKeyDoesNotIncreaseSize() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        map.put("a", 1);
        map.put("a", 2);
        map.put("a", 3);
        assertEquals(1, map.size());
        map.checkInvariants();
    }

    // ---------------------------------------------------------------- null handling

    @Test
    void putNullKeyThrowsNullPointerException() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        assertThrows(NullPointerException.class, () -> map.put(null, 1));
    }

    @Test
    void getNullKeyThrowsNullPointerException() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        assertThrows(NullPointerException.class, () -> map.get(null));
    }

    @Test
    void containsKeyNullKeyThrowsNullPointerException() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        assertThrows(NullPointerException.class, () -> map.containsKey(null));
    }

    @Test
    void removeNullKeyThrowsNullPointerException() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        assertThrows(NullPointerException.class, () -> map.remove(null));
    }

    @Test
    void failedPutWithNullKeyDoesNotChangeSize() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        assertThrows(NullPointerException.class, () -> map.put(null, 1));
        assertEquals(0, map.size());
    }

    @Test
    void nullValueCanBeStored() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        assertNull(map.put("a", null));
        assertTrue(map.containsKey("a"));
        assertNull(map.get("a"));
        assertEquals(1, map.size());
    }

    @Test
    void overwritingNullValueReturnsNullAsPreviousValue() {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        map.put("a", null);
        assertNull(map.put("a", 5));
        assertEquals(5, map.get("a"));
        assertEquals(1, map.size());
    }

    // ---------------------------------------------------------------- hash collisions

    @Test
    void collidingKeysCanBothBeRetrieved() {
        MyHashMap<TestKey, String> map = new MyHashMap<>();
        TestKey first = new TestKey("first", 42);
        TestKey second = new TestKey("second", 42);
        map.put(first, "one");
        map.put(second, "two");
        assertEquals("one", map.get(first));
        assertEquals("two", map.get(second));
        assertEquals(2, map.size());
        map.checkInvariants();
    }

    @Test
    void collidingKeyThatWasNeverInsertedIsNotFound() {
        MyHashMap<TestKey, String> map = new MyHashMap<>();
        map.put(new TestKey("first", 42), "one");
        TestKey stranger = new TestKey("stranger", 42);
        assertNull(map.get(stranger));
        assertFalse(map.containsKey(stranger));
    }

    @Test
    void overwritingOneCollidingKeyDoesNotAffectTheOther() {
        MyHashMap<TestKey, String> map = new MyHashMap<>();
        TestKey first = new TestKey("first", 42);
        TestKey second = new TestKey("second", 42);
        map.put(first, "one");
        map.put(second, "two");
        assertEquals("one", map.put(first, "uno"));
        assertEquals("uno", map.get(first));
        assertEquals("two", map.get(second));
        assertEquals(2, map.size());
    }

    // ---------------------------------------------------------------- negative hash codes

    @Test
    void negativeHashCodeKeyCanBeStoredAndRetrieved() {
        MyHashMap<TestKey, String> map = new MyHashMap<>();
        TestKey key = new TestKey("neg", -7);
        map.put(key, "value");
        assertEquals("value", map.get(key));
        assertTrue(map.containsKey(key));
        map.checkInvariants();
    }

    @Test
    void minimumIntegerHashCodeKeyCanBeStoredAndRetrieved() {
        MyHashMap<TestKey, String> map = new MyHashMap<>();
        TestKey key = new TestKey("min", Integer.MIN_VALUE);
        map.put(key, "value");
        assertEquals("value", map.get(key));
        map.checkInvariants();
    }

    @Test
    void negativeHashCodeKeyCanBeRemoved() {
        MyHashMap<TestKey, String> map = new MyHashMap<>();
        TestKey key = new TestKey("neg", -7);
        map.put(key, "value");
        assertEquals("value", map.remove(key));
        assertFalse(map.containsKey(key));
        assertEquals(0, map.size());
    }

    // ---------------------------------------------------------------- resizing

    @Test
    void capacityIsSixteenByDefault() {
        MyHashMap<Integer, Integer> map = new MyHashMap<>();
        assertEquals(16, map.capacity());
    }

    @Test
    void capacityDoesNotGrowWhileLoadFactorIsNotExceeded() {
        MyHashMap<Integer, Integer> map = new MyHashMap<>();
        for (int i = 0; i < 12; i++) {
            map.put(i, i);
        }
        assertEquals(16, map.capacity());
    }

    @Test
    void capacityDoublesWhenLoadFactorIsExceeded() {
        MyHashMap<Integer, Integer> map = new MyHashMap<>();
        for (int i = 0; i < 13; i++) {
            map.put(i, i);
        }
        assertEquals(32, map.capacity());
        map.checkInvariants();
    }

    @Test
    void allEntriesRemainRetrievableAfterResize() {
        MyHashMap<Integer, String> map = new MyHashMap<>();
        for (int i = 0; i < 100; i++) {
            map.put(i, "value" + i);
        }
        assertEquals(100, map.size());
        for (int i = 0; i < 100; i++) {
            assertEquals("value" + i, map.get(i));
        }
        map.checkInvariants();
    }

    @Test
    void sizeIsUnchangedByResize() {
        MyHashMap<Integer, Integer> map = new MyHashMap<>(2);
        for (int i = 0; i < 10; i++) {
            map.put(i, i);
            assertEquals(i + 1, map.size());
        }
    }

    // ---------------------------------------------------------------- remove from chains

    private MyHashMap<TestKey, String> mapWithChainOfThree(TestKey a, TestKey b, TestKey c) {
        MyHashMap<TestKey, String> map = new MyHashMap<>();
        map.put(a, "A");
        map.put(b, "B");
        map.put(c, "C");
        return map;
    }

    @Test
    void removeHeadOfChainReturnsItsValueAndKeepsOthers() {
        TestKey a = new TestKey("a", 5);
        TestKey b = new TestKey("b", 5);
        TestKey c = new TestKey("c", 5);
        MyHashMap<TestKey, String> map = mapWithChainOfThree(a, b, c);

        assertEquals("C", map.remove(c)); // last inserted is the head of the chain
        assertFalse(map.containsKey(c));
        assertEquals("A", map.get(a));
        assertEquals("B", map.get(b));
        assertEquals(2, map.size());
        map.checkInvariants();
    }

    @Test
    void removeMiddleOfChainReturnsItsValueAndKeepsOthers() {
        TestKey a = new TestKey("a", 5);
        TestKey b = new TestKey("b", 5);
        TestKey c = new TestKey("c", 5);
        MyHashMap<TestKey, String> map = mapWithChainOfThree(a, b, c);

        assertEquals("B", map.remove(b));
        assertFalse(map.containsKey(b));
        assertEquals("A", map.get(a));
        assertEquals("C", map.get(c));
        assertEquals(2, map.size());
        map.checkInvariants();
    }

    @Test
    void removeTailOfChainReturnsItsValueAndKeepsOthers() {
        TestKey a = new TestKey("a", 5);
        TestKey b = new TestKey("b", 5);
        TestKey c = new TestKey("c", 5);
        MyHashMap<TestKey, String> map = mapWithChainOfThree(a, b, c);

        assertEquals("A", map.remove(a)); // first inserted is the tail of the chain
        assertFalse(map.containsKey(a));
        assertEquals("B", map.get(b));
        assertEquals("C", map.get(c));
        assertEquals(2, map.size());
        map.checkInvariants();
    }

    @Test
    void removeAbsentKeyFromChainReturnsNullAndKeepsSize() {
        TestKey a = new TestKey("a", 5);
        TestKey b = new TestKey("b", 5);
        TestKey c = new TestKey("c", 5);
        MyHashMap<TestKey, String> map = mapWithChainOfThree(a, b, c);

        assertNull(map.remove(new TestKey("absent", 5)));
        assertEquals(3, map.size());
    }

    @Test
    void removingAllKeysOfChainEmptiesMap() {
        TestKey a = new TestKey("a", 5);
        TestKey b = new TestKey("b", 5);
        TestKey c = new TestKey("c", 5);
        MyHashMap<TestKey, String> map = mapWithChainOfThree(a, b, c);

        map.remove(b);
        map.remove(c);
        map.remove(a);
        assertTrue(map.isEmpty());
        assertEquals(0, map.size());
        map.checkInvariants();
    }

    // ---------------------------------------------------------------- clear and constructor

    @Test
    void clearRemovesAllEntries() {
        MyHashMap<Integer, Integer> map = new MyHashMap<>();
        for (int i = 0; i < 20; i++) {
            map.put(i, i);
        }
        map.clear();
        assertTrue(map.isEmpty());
        assertNull(map.get(5));
        map.checkInvariants();
    }

    @Test
    void zeroInitialCapacityThrowsIllegalArgumentException() {
        assertThrows(IllegalArgumentException.class, () -> new MyHashMap<String, String>(0));
    }

    @Test
    void negativeInitialCapacityThrowsIllegalArgumentException() {
        assertThrows(IllegalArgumentException.class, () -> new MyHashMap<String, String>(-3));
    }
}
